/*
 * The background half of web push.
 *
 * A page that is closed cannot show a notification, so Firebase needs a worker
 * of its own that the browser can wake. This is that worker, and it is
 * deliberately the smallest thing that can work: it initialises Firebase,
 * hands background messages to the browser, and routes a click.
 *
 * ## Why this is a second service worker
 *
 * PINGO already has one, generated by vite-plugin-pwa, which caches the app
 * shell. Firebase registers this file under its own scope
 * (`/firebase-cloud-messaging-push-scope`) rather than the root, so the two do
 * not fight over the same registration. Merging them would mean giving up
 * `generateSW` and hand-writing the caching strategy, which is a large amount
 * of risk to avoid one extra file.
 *
 * ## Why the config is inlined here rather than imported
 *
 * A service worker is fetched by the browser as a standalone script, outside
 * the bundle, so `import.meta.env` does not exist in it and Vite never
 * transforms it. The values below are the same ones the page uses, and none of
 * them is a secret: a Firebase web config ships in every client that uses it,
 * and the API key is restricted by origin rather than kept private.
 *
 * The consequence worth naming: changing the Firebase project means changing it
 * in two places. `firebase-config.ts` carries the same warning.
 */

importScripts('https://www.gstatic.com/firebasejs/10.14.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.14.1/firebase-messaging-compat.js');

firebase.initializeApp({
  apiKey: 'AIzaSyBM-moLL73RSgKzULVrEkeUNrJEJZtzdeY',
  authDomain: 'bingo-5176a.firebaseapp.com',
  projectId: 'bingo-5176a',
  storageBucket: 'bingo-5176a.firebasestorage.app',
  messagingSenderId: '896975933762',
  appId: '1:896975933762:web:be0d230cc8b1ef2dc6b8db',
});

const messaging = firebase.messaging();

/*
 * Background messages.
 *
 * The payload carries a `notification` block, which the browser displays on its
 * own - so this handler exists to add the things the browser cannot infer: a
 * tag, so a burst from one person replaces itself rather than stacking, and the
 * data needed to open the right screen on click.
 */
messaging.onBackgroundMessage((payload) => {
  const data = payload.data || {};
  const title = (payload.notification && payload.notification.title) || 'PINGO';
  const body = (payload.notification && payload.notification.body) || '';

  self.registration.showNotification(title, {
    body,
    icon: '/pingo-icon.png',
    badge: '/pingo-icon.png',
    // Same collapsing rule as Android: one entry per sender and kind.
    tag: `${data.kind || 'pingo'}:${data.actorId || 'system'}`,
    renotify: true,
    data,
  });
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  const data = event.notification.data || {};
  const target = data.subjectId ? `/chats/${data.subjectId}` : '/chats';

  /*
   * Focus an open tab rather than opening another one. Somebody who already has
   * PINGO open does not want a second copy of it because they tapped a
   * notification.
   */
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          client.navigate(target);
          return client.focus();
        }
      }
      return self.clients.openWindow(target);
    }),
  );
});
